diff --git a/io/io.cpp b/io/io.cpp
index df95e1b..7fb6cbd 100644
--- a/io/io.cpp
+++ b/io/io.cpp
@@ -774,6 +774,25 @@ extern "C" bool c_vcenew()
 {
 /// @todo Scrivere il corpo della primitiva vcenew()
 // ( SOLUZIONE 2025-01-27
+    natl pid = getpid();
+    sem_wait(ce.mutex);
+    if (ce.vces[pid] != nullptr) {
+        sem_signal(ce.mutex);
+        abort_p();
+    }
+    vce_des *v = new vce_des;
+    if (!v) {
+        sem_signal(ce.mutex);
+        return false;
+    }
+    if (!vce_des_init(v)) {
+        delete v;
+        sem_signal(ce.mutex);
+        return false;
+    }
+    ce.vces[pid] = v;
+    sem_signal(ce.mutex);
+    return true;
 //   SOLUZIONE 2025-01-27 )
 }

@@ -816,6 +835,52 @@ extern "C" void estern_ce(natq)
 {
 /// @todo Scrivere il corpo del processo esterno
 // ( SOLUZIONE 2025-01-27
+    natl current = 0;
+    for (;;) {
+        wfi();
+        for (;;) {
+            natq result = evget();
+            if (result == 0xFFFFFFFF)
+                break;
+            if (result == 0) {
+                sem_wait(ce.mutex);
+                ce.busy = false;
+                vce_des *v = vce_des_next(current);
+                if (v) {
+                    natl c = vce_des_read(v);
+                    outputb(static_cast<natb>(c), ce.iTBR);
+                    ce.busy = true;
+                    if (v->terminated && v->n == 0) {
+                        delete v;
+                        ce.vces[current] = nullptr;
+                    }
+                }
+                for (natl i = 0; i < MAX_PROC; i++) {
+                    vce_des *w = ce.vces[i];
+                    if (w && w->waiting && w->n < VCE_BUFSIZE) {
+                        w->waiting = false;
+                        sem_signal(w->sync);
+                    }
+                }
+                sem_signal(ce.mutex);
+                break;
+            }
+            sem_wait(ce.mutex);
+            vce_des *v = ce.vces[result];
+            if (v) {
+                v->terminated = true;
+                if (v->waiting) {
+                    v->waiting = false;
+                    sem_signal(v->sync);
+                }
+                if (v->n == 0) {
+                    delete v;
+                    ce.vces[result] = nullptr;
+                }
+            }
+            sem_signal(ce.mutex);
+        }
+    }
 //   SOLUZIONE 2025-01-27 )
 }

